def f(g):
    g=[r[:] for r in g]; H=len(g); W=len(g[0])
    # line column: contains longest uniform nonzero run
    best=(-1,None)
    for cc in range(W):
        col=[g[r][cc] for r in range(H)]
        s=set(col)-{0}
        if len(s)==1:
            v=list(s)[0]
            runs=0; cur=0
            for x in col:
                if x==v: cur+=1
                else:
                    if cur>runs: runs=max(runs,cur); cur=0
            if cur>runs: runs=max(runs,cur)
            if runs>=best[0]: best=(runs,v,cc)
    n,v,c=best
    nz=[rr for rr in range(H) if any(g[rr][x]!=0 for x in range(c+1,W))]
    top=nz[0]; last=nz[-1]
    hh=last-top+1
    blk=[[g[rr][x] for x in range(c+1,W)] for rr in range(top,last+1)]
    out=[]
    for rr in range(H):
        row=g[rr][:]
        if g[rr][c]==v:
            kk=(rr-top)%hh
            row[:]=[v]+blk[kk]
        out.append(row)
    return out
